cardCss:
.idiom-card {
    background: var(--card-bg, #ffffff);
    border-radius: 16px;
    padding: 14px 18px;
    box-shadow: 0 1px 3px rgba(190, 18, 60, 0.05);
    border: 1px solid var(--line, #e6e6e6);
    border-left: 4px solid #be123c;
    margin-bottom: 16px;
    transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s;
}
.idiom-card:hover { transform: translateY(-3px); box-shadow: 0 10px 26px rgba(190, 18, 60, 0.10); border-color: #f9d0d0; }
.idiom-card:active { transform: scale(0.99); }
.idiom-card.enter { animation: cardIn 0.5s both; }
@keyframes cardIn {
    from { opacity: 0; transform: translateY(14px) scale(0.99); }
    to   { opacity: 1; transform: none; }
}
.idiom-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; gap: 8px; }
.idiom-basic { display: flex; align-items: center; gap: 10px; min-width: 0; }
.idiom-index { color: var(--ink-3, #64748b); font-size: calc(12px * var(--card-font-scale, 1)); font-weight: var(--card-font-weight, 600); }
.idiom-word { font-size: calc(30px * var(--card-font-scale, 1)); font-weight: 800; color: #be123c; letter-spacing: 4px; }
.idiom-tools { display: flex; gap: 6px; flex-shrink: 0; }
.idiom-tools .action-btn {
    width: 40px; height: 40px; border: none; background: var(--action-btn-bg, #f1f5f9);
    border-radius: 90px; cursor: pointer; display: flex; align-items: center; justify-content: center;
    color: var(--ink-3, #64748b); transition: all 0.2s;
}
.idiom-tools .action-btn svg, .action-btn i { width: 22px; height: 22px; transition: transform 0.18s; }
.idiom-tools .action-btn:hover { transform: translateY(-2px); }
.idiom-tools .action-btn:hover svg { transform: scale(1.1); }
.idiom-tools .act-play:hover { background: #be123c; color: #fff; box-shadow: 0 4px 12px rgba(190, 18, 60, 0.3); }
.idiom-tools .eye-btn { background: var(--action-btn-bg, #f1f5f9); color: var(--ink-3, #64748b); }
.idiom-tools .eye-btn:hover { background: var(--amber-soft, #fef3c7); color: var(--amber, #d97706); box-shadow: 0 4px 12px rgba(217, 119, 6, 0.3); }
.idiom-tools .eye-btn.is-active { background: var(--amber, #d97706); color: #fff; box-shadow: 0 4px 12px rgba(217, 119, 6, 0.3); }
.idiom-tools .act-mark:hover { background: var(--unknown-soft, #ffe4e6); color: var(--unknown, #f43f5e); box-shadow: 0 4px 12px rgba(244, 63, 94, 0.3); }
.idiom-tools .act-mark.is-active { background: var(--unknown, #f43f5e); color: #fff; box-shadow: 0 4px 14px rgba(244, 63, 94, 0.3); }
.idiom-tools .act-fav:hover { background: var(--amber-soft, #fef3c7); color: var(--amber, #d97706); box-shadow: 0 4px 12px rgba(217, 119, 6, 0.3); }
.idiom-tools .act-fav.is-active { background: var(--amber, #d97706); color: #fff; box-shadow: 0 4px 12px rgba(217, 119, 6, 0.3); }
.idiom-body { display: flex; flex-direction: column; gap: 6px; }
.idiom-section {
    padding: 10px 14px; border-radius: 8px;
    background: var(--slate-soft, #f1f5f9);
    display: none; line-height: 1.5;
}
.idiom-section.show { display: block; animation: fadeSlide 0.25s ease; }
@keyframes fadeSlide {
    from { opacity: 0; transform: translateY(-6px); }
    to   { opacity: 1; transform: translateY(0); }
}
.idiom-label {
    font-size: calc(10px * var(--card-font-scale, 1)); font-weight: var(--card-font-weight, 700); color: var(--ink-3, #64748b);
    text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 4px;
}
.idiom-pinyin { font-size: calc(15px * var(--card-font-scale, 1)); color: var(--ink-2, #475569); font-weight: 500; }
.idiom-meaning { font-size: calc(14px * var(--card-font-scale, 1)); color: var(--ink, #1d1d1d); }
.idiom-example { font-size: calc(14px * var(--card-font-scale, 1)); color: var(--ink-2, #475569); font-style: italic; }
.action-btn i { font-size: 18px; line-height: 1; }
.action-btn:hover i { transform: scale(1.1); }

cardJs:
(function () {
    'use strict';
    window.cardTemplate = {
        name: 'Chinese Idiom Card',
        fields: [
            { key: 'idiom', label: 'Idiom', hideable: false },
            { key: 'pinyin', label: 'Pinyin' },
            { key: 'meaning', label: 'Meaning' },
            { key: 'example', label: 'Example' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(key) { return hidden.has && hidden.has(key); }
            function wrap(key, content) { return isHidden(key) ? '' : content; }
            var markActive = data.is_unknown === 1 ? 'is-active' : '';
            var favActive = data.is_favorite === 1 ? 'is-active' : '';
            var meaningShow = data._showMeaning ? 'show' : '';
            var meaningActive = data._showMeaning ? 'is-active' : '';
            return '<div class="idiom-card ' + (data.is_unknown === 1 ? 'highlighted' : '') + '" data-card-id="' + data.id + '">' +
                '<div class="idiom-header">' +
                '<div class="idiom-basic">' +
                '<span class="idiom-index">' + String(data.current_order).padStart(2, '0') + '</span>' +
                wrap('idiom', '<span class="idiom-word">' + (d.idiom || '') + '</span>') +
                '</div>' +
                '<div class="idiom-tools">' +
                '<button class="action-btn act-play" data-action="play" data-tooltip="Play Pronunciation"><i class="fa-solid fa-volume-high"></i></button>' +
                '<button class="action-btn eye-btn act-eye ' + meaningActive + '" data-action="toggle-meaning" data-tooltip="Show Meaning"><i class="' + (data._showMeaning ? 'fa-solid' : 'fa-regular') + ' fa-eye"></i></button>' +
                '<button class="action-btn act-mark ' + markActive + '" data-action="mark" data-tooltip="Mark as Unknown"><i class="' + (data.is_unknown === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>' +
                '<button class="action-btn act-fav ' + favActive + '" data-action="favorite" data-tooltip="Favorite"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-bookmark"></i></button>' +
                '</div></div>' +
                '<div class="idiom-body">' +
                wrap('pinyin', '<div class="idiom-section show"><div class="idiom-label">Pinyin</div><div class="idiom-pinyin">' + (d.pinyin || '') + '</div></div>') +
                wrap('meaning', '<div class="idiom-section ' + meaningShow + '"><div class="idiom-label">释义</div><div class="idiom-meaning">' + (d.meaning || '') + '</div></div>') +
                wrap('example', '<div class="idiom-section show"><div class="idiom-label">例句</div><div class="idiom-example">' + (d.example || '') + '</div></div>') +
                '</div></div>';
        },
        init: function (cardElement, cardData, api) {
            cardElement.querySelector('[data-action="play"]').addEventListener('click', function () {
                var w = cardData.data && cardData.data.idiom;
                if (w) api.playAudio(w);
                api.track('audio_play');
            });
            cardElement.querySelector('[data-action="mark"]').addEventListener('click', function () {
                var self = this;
                api.toggleMark().then(function (dd) {
                    if (dd.success) {
                        cardElement.classList.toggle('highlighted');
                        self.classList.toggle('is-active');
                    }
                });
                api.track('word_mark');
            });
            var favBtn = cardElement.querySelector('[data-action="favorite"]');
            if (favBtn) {
                favBtn.addEventListener('click', function () {
                    var self = this;
                    api.toggleFavorite().then(function (dd) {
                        if (dd.success) self.classList.toggle('is-active');
                    });
                    api.track('favorite_toggle');
                });
            }
            var meaningBtn = cardElement.querySelector('[data-action="toggle-meaning"]');
            if (meaningBtn) {
                var meaningSec = cardElement.querySelector('.idiom-meaning');
                meaningBtn.addEventListener('click', function () {
                    if (cardData._showMeaning) {
                        clearTimeout(cardData._meaningTimer);
                        cardData._showMeaning = false;
                        if (meaningSec) meaningSec.parentElement.classList.remove('show');
                        meaningBtn.classList.remove('is-active');
                    } else {
                        cardData._showMeaning = true;
                        clearTimeout(cardData._meaningTimer);
                        if (meaningSec) meaningSec.parentElement.classList.add('show');
                        meaningBtn.classList.add('is-active');
                        cardData._meaningTimer = setTimeout(function () {
                            cardData._showMeaning = false;
                            if (meaningSec) meaningSec.parentElement.classList.remove('show');
                            meaningBtn.classList.remove('is-active');
                        }, 5000);
                    }
                });
            }
            cardElement.querySelectorAll('[data-action]').forEach(function (btn) {
                btn.addEventListener('mouseenter', function () {
                    var tooltip = btn.dataset.tooltip;
                    if (tooltip && api.showTooltip) api.showTooltip(btn, tooltip);
                });
                btn.addEventListener('mouseleave', function () {
                    if (api.hideTooltip) api.hideTooltip();
                });
            });
        },
        update: function (cardElement, cardData, api) {
            var p = cardElement.parentElement;
            if (p) { cardElement.outerHTML = this.render('', cardData, api); }
        }
    };
})();
